style.css:
@-moz-document regexp("https?://.*") {
/* Dit past de stijl toe op alle koppen van alle websites */
  h1, h2, h3, h4, h5, h6, .title, [class*="title"] {
    font-family: 'Arial Rounded MT Bold', 'Comic Sans MS', sans-serif !important;
    color: #4b0082 !important; /* Indigo / donkerpaars */
    
    /* Statisch 3D-suikereffect met paarse tinten */
    text-shadow: 
      1px 1px 0px #ffffff, 
      2px 2px 0px #dda0dd, /* Lichtpaars */
      3px 3px 0px #8a2be2 !important; /* Medium paars */
    
    /* Geen animaties */
    transition: none !important;
    animation: none !important;
  }
}
